    /** 게시글 마지막 수정 시각(ISO8601) */
    updated_at: string & tags.Format<"date-time">;

    /** 해당 글의 댓글 개수 */
    comment_count: number & tags.Type<"int32">;

    /** 해당 글의 추천(투표) 합계 */
    vote_count: number & tags.Type<"int32">;
  };

  /**
   * 게시글 검색, 필터, 페이징에 요청 정보로 사용되는 객체입니다.
