  TestValidator.equals("pagination metadata, page")(
    page,
  )(output.pagination.current);
  TestValidator.equals("pagination metadata, limit")(
    limit,
  )(output.pagination.limit);
  TestValidator.equals("pagination metadata, records")(
    expected.length,
  )(output.pagination.records);
  TestValidator.equals("pagination metadata, pages")(
    Math.ceil(expected.length / limit),
  )(output.pagination.pages);
}

