/**
 * Validate that an author can retrieve the full details of their own post by ID.
 *
 * This test confirms that, after creating a user (the author), a category, and a post assigned to that user and category, the author can retrieve the post by its ID and see all allowed fields, such as title, content, category, and timestamps. It ensures no restricted fields are leaked and that all field values match what was created.
 *
 * Scenario steps:
 * 1. Register a user to act as the author
 * 2. Create a category to assign the post to
 * 3. Create a post authored by the registered user in the created category
 * 4. Retrieve the post by its ID as the author
 * 5. Validate that all post details match and that no restricted fields are leaked
 */
export async function test_api_post_details_author_retrieval(connection: api.IConnection): Promise<void> {
  // 1. Register a new user (author)
  const userRoleId = typia.random<string & tags.Format<"uuid">>(); // assume a valid existing roleId, or could look up a default role if available
  const userInput: IUser.ICreate = {
    user_role_id: userRoleId,
    username: `author_${Math.random().toString(36).substring(2, 10)}`,
    email: `test_${Math.random().toString(36).substring(2, 8)}@example.com`,
    bio: "Test author bio",
    password: "password123!",
    status: "active",
  };
  const author: IUser = await api.functional.core.users.post(connection, {
    body: userInput,
  });
  typia.assert(author);
  TestValidator.equals("user role id matches")(userInput.user_role_id)(author.user_role_id);
  TestValidator.equals("username matches")(userInput.username)(author.username);
  TestValidator.equals("email matches")(userInput.email)(author.email);

  // 2. Create a category
  const categoryInput: ICategory.ICreate = {
    name: `TestCategory_${Math.random().toString(36).substring(2, 6)}`,
    description: "Test category for post retrieval",
  };
  const category: ICategory = await api.functional.core.categories.post(connection, {
    body: categoryInput,
  });
  typia.assert(category);
  TestValidator.equals("category name matches")(categoryInput.name)(category.name);

  // 3. Create a post authored by the registered user in the created category
  const postInput: IPost.ICreate = {
    category_id: category.id,
    title: `Test Post ${Math.random().toString(36).substring(2, 8)}`,
    content: "This is a test post content.",
    user_id: author.id,
  };
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: postInput,
  });
  typia.assert(post);
  TestValidator.equals("post user id matches")(author.id)(post.user_id);
  TestValidator.equals("post category matches")(category.id)(post.category_id);
  TestValidator.equals("post title matches")(postInput.title)(post.title);
  TestValidator.equals("post content matches")(postInput.content)(post.content);

  // 4. Retrieve the post by its ID as the author
  const retrieved: IPost = await api.functional.posts.posts.getById(connection, {
    id: post.id,
  });
  typia.assert(retrieved);
  // 5. Validate all post details and that restricted fields are not present
  TestValidator.equals("post id matches")(post.id)(retrieved.id);
  TestValidator.equals("author id matches")(post.user_id)(retrieved.user_id);
  TestValidator.equals("category id matches")(post.category_id)(retrieved.category_id);
  TestValidator.equals("title matches")(post.title)(retrieved.title);
  TestValidator.equals("content matches")(post.content)(retrieved.content);
  TestValidator.equals("created_at matches")(post.created_at)(retrieved.created_at);
  TestValidator.equals("updated_at matches")(post.updated_at)(retrieved.updated_at);
  // deleted_at is optional nullable, should match
  TestValidator.equals("deleted_at matches")((post.deleted_at ?? null))(retrieved.deleted_at ?? null);

  // Confirm no restricted fields are exposed -- our DTO is already strict; extra keys would violate the type.
  // If business logic needs to check, use typia/predicate for unexpected fields.
}

