import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import type { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test filtered retrieval of comments by a specific user.
 *
 * Validates that, after creating a user and several comments on different posts (by this and other users),
 * the filtering endpoint correctly returns only those comments authored by the target user, supporting proper pagination and ordering.
 *
 * 1. Register 'target' user (whose comments will be filtered by).
 * 2. Register a second user (to create comments from others).
 * 3. Create multiple posts.
 * 4. Add several comments by both users to various posts.
 * 5. Fetch comments with userId filter set to target user,
 *    verify only target user's comments are returned.
 * 6. Check that pagination and ordering work as intended.
 */
export async function test_api_comment_list_comments_by_user_id(connection: api.IConnection): Promise<void> {
  // 1. Register target user
  const targetUserBody = {
    username: `target_user_${Math.floor(Math.random() * 100000)}`,
    email: `targetuser_${Math.floor(Math.random() * 100000)}@example.com`,
    user_role_id: typia.random<string & tags.Format<'uuid'>>(),
    password: 'testpassword1!',
    status: 'active',
  } satisfies IUser.ICreate;
  const targetUser: IUser = await api.functional.core.users.post(connection, { body: targetUserBody });
  typia.assert(targetUser);

  // 2. Register other user
  const otherUserBody = {
    username: `other_user_${Math.floor(Math.random() * 100000)}`,
    email: `otheruser_${Math.floor(Math.random() * 100000)}@example.com`,
    user_role_id: targetUser.user_role_id,
    password: 'testpassword2!',
    status: 'active',
  } satisfies IUser.ICreate;
  const otherUser: IUser = await api.functional.core.users.post(connection, { body: otherUserBody });
  typia.assert(otherUser);

  // 3. Create multiple posts
  const postBodies: IPost.ICreate[] = [0,1,2].map(i => ({
    user_id: targetUser.id,
    category_id: typia.random<string & tags.Format<'uuid'>>(),
    title: `Post Title ${i}`,
    content: `Post Content ${i}`,
  }));
  const posts: IPost[] = [];
  for (const body of postBodies) {
    const post: IPost = await api.functional.posts.posts.post(connection, { body });
    typia.assert(post);
    posts.push(post);
  }

  // 4. Add several comments by both users on different posts
  // We'll keep track which comments belong to which author
  interface AuthComment { comment: IComment; author: IUser; }
  const authoredComments: AuthComment[] = [];
  for (let i = 0; i < 9; ++i) {
    // Alternate user for each comment
    const author = (i % 2 === 0 ? targetUser : otherUser);
    const post = posts[i % posts.length];
    const commentBody: IComment.ICreate = {
      user_id: author.id,
      post_id: post.id,
      content: `Comment ${i} by ${author.username}`,
    };
    const comment: IComment = await api.functional.posts.comments.post(connection, { body: commentBody });
    typia.assert(comment);
    authoredComments.push({ comment, author });
  }

  // 5. Fetch comments filtering by target user's id
  const req: IComment.IRequest = {
    userId: targetUser.id,
    limit: 20,
    sort: 'created_at:asc',
  };
  const page: IPageIComment = await api.functional.posts.comments.patch(connection, { body: req });
  typia.assert(page);

  // 6. Validate only target user's comments are returned, with correct ordering
  // Find the set of comment IDs that should match
  const expectedTargetComments: IComment[] = authoredComments.filter(ac => ac.author.id === targetUser.id).map(ac => ac.comment);
  // Should be sorted by created_at ASC due to the request
  expectedTargetComments.sort((a, b) => a.created_at.localeCompare(b.created_at));

  // Returned data consists of IComment.ISummary
  TestValidator.equals("Should return all target user's comments only")(
    expectedTargetComments.length
  )(page.data.length);
  for (let idx = 0; idx < expectedTargetComments.length; ++idx) {
    const summary = page.data[idx];
    const expected = expectedTargetComments[idx];
    TestValidator.equals(`User ID for comment #${idx}`)(targetUser.id)(summary.user_id);
    TestValidator.equals(`Comment ID order for comment #${idx}`)(expected.id)(summary.id);
    TestValidator.equals(`Post ID for comment #${idx}`)(expected.post_id)(summary.post_id);
    // parent_id may be undefined/null always since top-level comments
    TestValidator.equals(`Parent ID for comment #${idx}`)(expected.parent_id ?? null)(summary.parent_id ?? null);
    TestValidator.predicate(`created_at type for comment #${idx}`)(() => typeof summary.created_at === "string");
  }

  // Pagination sanity check
  TestValidator.equals("pagination.records matches number of results")(
    expectedTargetComments.length
  )(page.pagination.records);
  TestValidator.equals("limit equals requested page size")(
    req.limit
  )(page.pagination.limit);
  TestValidator.equals("current page is 1")(
    1
  )(page.pagination.current);
}

