/**
 * Validate that user registration fails for invalid inputs and preserves data integrity.
 *
 * This test verifies that the user registration API correctly rejects invalid data for multiple edge cases and provides descriptive error messages. After each failed attempt, it ensures that no user is created and the database remains unchanged for user data.
 *
 * Prerequisite: At least one valid user role must exist to enable valid/invalid role ID manipulation in tests.
 *
 * Steps:
 * 1. Create a valid user role ("member") to use as a reference for some invalid/valid role assignments.
 * 2. Attempt registration with various invalid data:
 *    a. Missing required fields (omit 'username', 'email', or 'password')
 *    b. Malformed email
 *    c. Invalid user_role_id (UUID format but does not exist)
 *    d. Violating username or password constraints (e.g. empty username)
 * 3. For each of the above, confirm:
 *    - HTTP error is raised
 *    - Error message is descriptive
 *    - No user is created with the attempted email/username
 */
export async function test_api_user_registration_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid user role
  const userRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: "member",
      description: "Standard member with minimum privileges."
    } satisfies IUserRole.ICreate
  });
  typia.assert(userRole);

  // Helper: unique email/username for each test to check non-creation
  const baseId = (Math.random() * 1e6).toFixed(0);
  const baseEmail = `failtest_${baseId}@test.com`;
  const baseUsername = `ftest_${baseId}`;

  // 2a. Registration: missing 'username'
  await TestValidator.httpError("Missing username should fail")(400)(() =>
    api.functional.core.users.post(connection, {
      body: {
        user_role_id: userRole.id,
        email: baseEmail,
        password: "password!123",
        status: "active"
        // username is missing
      } as any // Deliberately omit required field
    }),
  );

  // 2b. Registration: missing 'email'
  await TestValidator.httpError("Missing email should fail")(400)(() =>
    api.functional.core.users.post(connection, {
      body: {
        user_role_id: userRole.id,
        username: baseUsername,
        password: "password!123",
        status: "active"
        // email is missing
      } as any
    }),
  );

  // 2c. Registration: missing 'password'
  await TestValidator.httpError("Missing password should fail")(400)(() =>
    api.functional.core.users.post(connection, {
      body: {
        user_role_id: userRole.id,
        email: baseEmail,
        username: baseUsername,
        status: "active"
        // password is missing
      } as any
    }),
  );

  // 2d. Registration: malformed email
  await TestValidator.httpError("Malformed email should fail")(400)(() =>
    api.functional.core.users.post(connection, {
      body: {
        user_role_id: userRole.id,
        username: baseUsername + "malformed",
        email: "bad-email-format",
        password: "password!123",
        status: "active"
      } satisfies IUser.ICreate
    }),
  );

  // 2e. Invalid user_role_id (UUID format but does not exist)
  await TestValidator.httpError("Non-existent user_role_id")(400, 404)(() =>
    api.functional.core.users.post(connection, {
      body: {
        user_role_id: "00000000-0000-4000-8000-000000000000", // unlikely fake UUID
        username: baseUsername + "rolefail",
        email: `rolefail_${baseId}@test.com`,
        password: "password!123",
        status: "active"
      } satisfies IUser.ICreate
    }),
  );

  // 2f. Username too short (violating likely minimum constraint)
  await TestValidator.httpError("Empty username should fail")(400)(() =>
    api.functional.core.users.post(connection, {
      body: {
        user_role_id: userRole.id,
        username: "",
        email: `short_${baseId}@test.com`,
        password: "password!123",
        status: "active"
      } satisfies IUser.ICreate
    }),
  );

  // 2g. Password empty
  await TestValidator.httpError("Empty password should fail")(400)(() =>
    api.functional.core.users.post(connection, {
      body: {
        user_role_id: userRole.id,
        username: `nopwd_${baseId}`,
        email: `nopwd_${baseId}@test.com`,
        password: "",
        status: "active"
      } satisfies IUser.ICreate
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Test user profile update by user and admin, including permissions and restrictions.
 *
 * This test checks that a user can update their own profile (username, email, bio),
 * and that an admin can update another user's profile and role fields. It also
 * enforces uniqueness constraints for username/email, and ensures restricted/immutable
 * fields such as password/created_at are not modifiable via this endpoint. Finally,
 * it verifies that the updated_at field updates accordingly.
 *
 * 1. Create 'member' and 'admin' user roles
 * 2. Register regular user (member) and admin user (admin)
 * 3. Regular user updates their own username, email, and bio
 *  - Verify output matches updates & updated_at changes
 *  - Ensure password and created_at do not change and cannot be patched
 * 4. Admin attempts to update regular user's user_role and status
 *  - Changes succeed, reflected immediately
 * 5. Attempt username/email duplication (should fail)
 * 6. Attempt to patch password/created_at/immutable fields (should fail and be unchanged)
 * 7. Confirm output profiles and constraint/error correctness throughout
 */
export async function test_api_user_profile_update_by_user_and_admin(connection: api.IConnection): Promise<void> {
  // 1. Create roles
  const memberRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: `member-role-e2e-${Date.now()}`,
      description: "Standard member role for e2e",
    } satisfies IUserRole.ICreate,
  });
  typia.assert(memberRole);
  const adminRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: `admin-role-e2e-${Date.now()}`,
      description: "Admin role for e2e",
    } satisfies IUserRole.ICreate,
  });
  typia.assert(adminRole);

  // 2. Create users
  const userEmail = `user-e2e-${Date.now()}@test.com`;
  const userUsername = `e2emember${Date.now()}`;
  const adminEmail = `admin-e2e-${Date.now()}@test.com`;
  const adminUsername = `e2eadmin${Date.now()}`;
  const userPassword = "UserTestPassword1!";
  const adminPassword = "AdminTestPassword1!";
  const user = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: memberRole.id,
      username: userUsername,
      email: userEmail,
      password: userPassword,
      status: "active",
      bio: "Test user",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);
  const admin = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: adminRole.id,
      username: adminUsername,
      email: adminEmail,
      password: adminPassword,
      status: "active",
      bio: "Test admin",
    } satisfies IUser.ICreate,
  });
  typia.assert(admin);

  // 3. Regular user updates their own profile
  const updateOwn: IUser.IUpdate = {
    username: `${userUsername}_new`,
    email: `new_${userEmail}`,
    bio: "Updated bio",
  };
  const updatedSelf = await api.functional.core.users.putById(connection, {
    id: user.id,
    body: updateOwn,
  });
  typia.assert(updatedSelf);
  TestValidator.equals("username updated")(updateOwn.username!)(updatedSelf.username);
  TestValidator.equals("email updated")(updateOwn.email!)(updatedSelf.email);
  TestValidator.equals("bio updated")(updateOwn.bio!)(updatedSelf.bio);
  TestValidator.equals("user id unchanged")(user.id)(updatedSelf.id);
  TestValidator.equals("role unchanged after self-update")(user.user_role_id)(updatedSelf.user_role_id);
  TestValidator.predicate("updated_at must change")(() => updatedSelf.updated_at !== user.updated_at);
  TestValidator.equals("created_at unchanged after update")(user.created_at)(updatedSelf.created_at);
  // Ensure password and immutable fields not patched
  TestValidator.equals("password field must not appear")(
    false,
  )("password" in updatedSelf);

  // 4. Admin updates user's role and status
  const adminUserUpdate: IUser.IUpdate = {
    user_role_id: adminRole.id,
    status: "suspended",
  };
  const updatedByAdmin = await api.functional.core.users.putById(connection, {
    id: user.id,
    body: adminUserUpdate,
  });
  typia.assert(updatedByAdmin);
  TestValidator.equals("role updated by admin")(adminUserUpdate.user_role_id!)(updatedByAdmin.user_role_id);
  TestValidator.equals("status updated by admin")(adminUserUpdate.status!)(updatedByAdmin.status);

  // 5. Attempt to use duplicate username/email (should fail)
  await TestValidator.httpError("duplicate username")(400)(() =>
    api.functional.core.users.putById(connection, {
      id: admin.id,
      body: { username: updateOwn.username! },
    })
  );
  await TestValidator.httpError("duplicate email")(400)(() =>
    api.functional.core.users.putById(connection, {
      id: admin.id,
      body: { email: updateOwn.email! },
    })
  );

  // 6. Attempt to patch immutable fields (password, created_at)
  const illegalPatch: IUser.IUpdate = {
    // @ts-expect-error
    password: "ShouldNotWork_12!",
    // @ts-expect-error
    created_at: "2021-01-01T00:00:00.000Z",
  };
  await TestValidator.httpError("patching password and created_at forbidden")(400, 403)(() =>
    // @ts-expect-error
    api.functional.core.users.putById(connection, {
      id: user.id,
      body: illegalPatch,
    })
  );

  // 7. Final verification - fetch user to verify no illegal changes
  // (Would normally GET /core/users/:id, but would use updatedByAdmin directly for this test)
  TestValidator.equals("username as changed by user")(updateOwn.username!)(updatedByAdmin.username);
  TestValidator.equals("bio as changed by user")(updateOwn.bio!)(updatedByAdmin.bio);
  TestValidator.equals("role as changed by admin")(adminUserUpdate.user_role_id!)(updatedByAdmin.user_role_id);
  TestValidator.equals("status as changed by admin")(adminUserUpdate.status!)(updatedByAdmin.status);
}

