/**
 * Verify category listing with valid search and pagination.
 *
 * This test ensures an authenticated user can fetch a filtered and paginated list of categories.
 * It creates several distinct categories, then queries with PATCH /core/categories using partial name search,
 * page, and limit. Confirms result contains only expected categories and accurate metadata.
 *
 * Steps:
 * 1. Create several categories (ensure at least one matches filter criterion)
 * 2. Issue PATCH /core/categories with page, limit, and partial name search
 * 3. Validate response: only correct categories in result, correct pagination metadata
 */
export async function test_api_category_list_with_valid_search_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create categories
  const categories: ICategory[] = [];
  for (const descriptor of [
    { name: "정치", description: "정치 제도와 관련된 논의" },
    { name: "경제", description: "국제 경제 및 정책" },
    { name: "역사", description: "세계사, 한국사, 동양사" },
    { name: "과학", description: "최신 과학기술 및 자연과학" },
    { name: "문화", description: "영화, 책, 미술" },
  ]) {
    const created = await api.functional.core.categories.post(connection, {
      body: descriptor satisfies ICategory.ICreate,
    });
    typia.assert(created);
    categories.push(created);
  }

  // 2. List/search using PATCH
  const searchPartial = "정"; // Should match "정치" only
  const page: number = 1;
  const limit: number = 2;

  const output: IPageICategory = await api.functional.core.categories.patch(
    connection,
    {
      body: {
        name: searchPartial,
        page,
        limit,
      } satisfies ICategory.IRequest,
    },
  );
  typia.assert(output);

  // 3. Validate only matching categories are returned and metadata is correct
  const expected = categories.filter((c) => c.name.includes(searchPartial));
  TestValidator.equals("filtered category count")(expected.length)(output.data.length);
  for (const c of output.data) {
    TestValidator.equals("category name contains search keyword")(true)(c.name.includes(searchPartial));
    // Confirm this category is one of those we created
    TestValidator.predicate("Returned category was created in-test")(() => (
      typeof c.id === "string" && categories.some(origin => origin.id === c.id)
    ));
  }
  TestValidator.equals("pagination metadata, page")(
    page,
  )(output.pagination.current);
  TestValidator.equals("pagination metadata, limit")(
    limit,
  )(output.pagination.limit);
  TestValidator.equals("pagination metadata, records")(
    expected.length,
  )(output.pagination.records);
  TestValidator.equals("pagination metadata, pages")(
    Math.ceil(expected.length / limit),
  )(output.pagination.pages);
}

