/**
 * Test deletion failure when the category is in use by posts.
 *
 * This test ensures that the system enforces business integrity by rejecting deletion
 * of a category currently associated with one or more posts.
 * The system should respond with a proper error (e.g., conflict or rejection)
 * when deletion is attempted.
 *
 * **Process**
 * 1. Create a new category
 * 2. Create a post using the above category
 * 3. Attempt to delete the category (should fail)
 *
 * The test expects the deletion attempt to fail and return a clear error.
 */
export async function test_api_category_delete_failure_in_use_by_post(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new category
  const category = await api.functional.core.categories.post(connection, {
    body: {
      name: `정치-${Date.now()}`,
      description: "토론 게시판 테스트용 카테고리입니다.",
    } satisfies ICategory.ICreate,
  });
  typia.assert(category);

  // 2. Create a new post using this category and a random user
  const userId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: category.id,
      title: "게시글 제목 (카테고리 삭제 테스트)",
