import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import type { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";
import type { IPageIPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function test_api_post_list_default(connection: api.IConnection): Promise<void> {
  // 1. Register a user account for post creation
  const userBody: IUser.ICreate = {
    user_role_id: typia.random<string & tags.Format<"uuid">>(),
    username: `test_user_${Date.now()}`,
    email: `test_user_${Date.now()}@example.com`,
    bio: "Test user bio",
    password: "securePass123!",
    status: "active"
  };
  const user: IUser = await api.functional.core.users.post(connection, { body: userBody });
  typia.assert(user);

  // 2. Create a category (required field for posts)
  const categoryBody: ICategory.ICreate = {
    name: `category_${Date.now()}`,
    description: "Default category for posts."
  };
  const category: ICategory = await api.functional.core.categories.post(connection, { body: categoryBody });
  typia.assert(category);

  // 3. Create a post linked to above user and category
  const postBody: IPost.ICreate = {
    category_id: category.id,
    title: `Sample Post Title ${Date.now()}`,
    content: "This is the content of the sample post.",
    user_id: user.id
  };
  const createdPost: IPost = await api.functional.posts.posts.post(connection, { body: postBody });
  typia.assert(createdPost);

  // 4. Retrieve the default post list (empty filter, default paged)
  const req: IPost.IRequest = {
    page: 1,
    limit: 100
  };
  const output: IPageIPost = await api.functional.posts.posts.patch(connection, { body: req });
  typia.assert(output);

  // 5. List should include the created post and it should not be deleted
  const match = output.data.find((p) => p.id === createdPost.id);
  TestValidator.predicate("Created post must be present in default list")(() => !!match);
  if (!match) throw new Error("Created post missing from listing!");
  TestValidator.equals("Deleted_at should be null for active post")(match.deleted_at ?? null)(null);
  TestValidator.equals("Author and category of post should match")(createdPost.user_id)(match.user_id);
  TestValidator.equals("Category of post should match")(createdPost.category_id)(match.category_id);
  TestValidator.equals("Title should match")(createdPost.title)(match.title);

  // 6. Validate pagination metadata
  TestValidator.equals("Pagination limit matches request")(req.limit)(output.pagination.limit);
  TestValidator.equals("Current page is correct")(req.page)(output.pagination.current);
  TestValidator.predicate("Output data array must include at least 1 post")(() => output.data.length >= 1);
  TestValidator.equals("Records should match output data length if only 1 post exists or more")(
    output.data.length
  )(output.pagination.records);
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import type { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";
import type { IPageIPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that when filtering the post list by a specific category, only posts assigned to that category are returned.
 *
 * Scenario Background: We want to ensure the filter and search mechanism for posts by category works as intended. This test sets up a user, two categories, and creates posts in each—then verifies that we can successfully filter by category using the list API, with counts and pagination reflecting only the filtered posts.
 *
 * Steps:
 * 1. Create a user for post creation.
 * 2. Create two distinct categories.
 * 3. Create one post in the first category and another post in the second category.
 * 4. List posts with a filter on the first category.
 * 5. Confirm that only the first post is returned, the second post is excluded, and the record count in pagination is correct.
 * 6. (Optional) Repeat for the second category.
 */
export async function test_api_post_list_with_category_filter(connection: api.IConnection): Promise<void> {
  // 1. Create a user
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const userCreate: IUser.ICreate = {
    user_role_id: roleId,
    username: `testuser_${Date.now()}`,
    email: `testuser_${Date.now()}@wrtn.io`,
    bio: "Post filtering test user",
    password: "test1234",
    status: "active",
  };
  const user: IUser = await api.functional.core.users.post(connection, { body: userCreate });
  typia.assert(user);

  // 2. Create two distinct categories
  const categoryCreateA: ICategory.ICreate = {
    name: `CategoryA_${Date.now()}`,
    description: "Test category A",
  };
  const categoryA: ICategory = await api.functional.core.categories.post(connection, { body: categoryCreateA });
  typia.assert(categoryA);

  const categoryCreateB: ICategory.ICreate = {
    name: `CategoryB_${Date.now()}`,
    description: "Test category B",
  };
  const categoryB: ICategory = await api.functional.core.categories.post(connection, { body: categoryCreateB });
  typia.assert(categoryB);

  // 3. Create one post in each category
  const postA: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: categoryA.id,
      title: `Post in A at ${Date.now()}`,
      content: "This is content for post in category A.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postA);

  const postB: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: categoryB.id,
      title: `Post in B at ${Date.now()}`,
      content: "This is content for post in category B.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postB);

  // 4. List posts filtering by categoryA
  const listA = await api.functional.posts.posts.patch(connection, {
    body: {
      category_id: categoryA.id,
      page: 1,
      limit: 10,
    } satisfies IPost.IRequest,
  });
  typia.assert(listA);

  // 5. Check that only postA is in the list, not postB
  TestValidator.equals("Returned post count should be 1 after filtering by CategoryA")(1)(listA.data.length);
  TestValidator.equals("Only the filtered post's ID should appear")([postA.id])(listA.data.map(p => p.id));
  TestValidator.predicate("Result post should be in requested category")(() => listA.data.every(p => p.category_id === categoryA.id));
  TestValidator.equals("Pagination records should match")(1)(listA.pagination.records);

  // 6. List posts filtering by categoryB
  const listB = await api.functional.posts.posts.patch(connection, {
    body: {
      category_id: categoryB.id,
      page: 1,
      limit: 10,
    } satisfies IPost.IRequest,
  });
  typia.assert(listB);
  TestValidator.equals("Returned post count should be 1 after filtering by CategoryB")(1)(listB.data.length);
  TestValidator.equals("Only the filtered post's ID should appear")([postB.id])(listB.data.map(p => p.id));
  TestValidator.predicate("Result post should be in requested category")(() => listB.data.every(p => p.category_id === categoryB.id));
  TestValidator.equals("Pagination records should match")(1)(listB.pagination.records);
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import type { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";
import type { IPageIPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test combined keyword search and author filter on posts.
 *
 * This test validates that when posts are created by two different users with overlapping keywords in their post titles/content, the API correctly returns only the posts which both match the search keyword and are authored by the specified user. This demonstrates that author and keyword filters work in combination, not just independently.
 *
 * Scenario steps:
 * 1. Register two distinct users.
 * 2. Create a new category for the posts.
 * 3. User A creates two posts, each with distinct keywords.
 * 4. User B creates two posts, one of which uses a keyword also used by User A.
 * 5. Execute a post search filtering by User B's user_id and a keyword common to both users (should only return User B's relevant post).
 * 6. Assert that only the expected post(s) by User B, containing the search keyword, are returned.
 */
export async function test_api_post_list_keyword_and_author_filter(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register two users.
  const userA: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: "00000000-0000-0000-0000-000000000001", // Assume standard role for test
      username: `userA_${Date.now()}`,
      email: `userA_${Date.now()}@test.com`,
      password: "testpass123",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(userA);

  const userB: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: "00000000-0000-0000-0000-000000000001", // Assume standard role for test
      username: `userB_${Date.now()}`,
      email: `userB_${Date.now()}@test.com`,
      password: "testpass123",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(userB);

  // 2. Create a category
  const category: ICategory = await api.functional.core.categories.post(connection, {
    body: {
      name: `e2e-filter-category-${Date.now()}`,
      description: "Category for filter test",
    } satisfies ICategory.ICreate,
  });
  typia.assert(category);

  // 3. User A creates two posts
  const keyword = "wrtnkeyword";
  const postA1: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: category.id,
      title: `E2E Test post keyword: ${keyword}`,
      content: "First post content by userA",
      user_id: userA.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postA1);

  const postA2: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: category.id,
      title: "Another post by userA",
      content: "Second post by userA does not contain keyword.",
      user_id: userA.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postA2);

  // 4. User B creates two posts, one sharing the keyword
  const postB1: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: category.id,
      title: `B - ${keyword} is here!`,
      content: "Post from userB sharing the keyword.",
      user_id: userB.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postB1);

  const postB2: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: category.id,
      title: "UserB unique post",
      content: "This is unique to userB.",
      user_id: userB.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postB2);

  // 5. List posts: filter by userB's id and keyword
  const res = await api.functional.posts.posts.patch(connection, {
    body: {
      user_id: userB.id,
      title: keyword,
      page: 1,
      limit: 10,
    } satisfies IPost.IRequest,
  });
  typia.assert(res);

  // 6. Assert that only postB1 is returned (since user_id=userB.id and title contains keyword)
  // There should be only 1 post (postB1), and it should have postB1's id and user_id
  TestValidator.equals("Should return exactly one post matching both filters")(1)(res.data.length);
  const rtn = res.data[0];
  TestValidator.equals("Result's id matches postB1")(postB1.id)(rtn.id);
  TestValidator.equals("Result user is userB")(userB.id)(rtn.user_id);
  TestValidator.predicate("Result title contains keyword")(() => rtn.title.includes(keyword));
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
