import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Attempt to list posts using invalid pagination parameters.
 *
 * This test ensures the posts listing API input validation logic for pagination: when sent negative numbers or zero for 'page' or 'limit', or excessively large values, the API should return clear and correct validation errors, never leaking internal data.
 *
 * 1. Attempt to list posts with a negative page number (page: -1)
 * 2. Attempt to list posts with page = 0 (invalid, as minimum is 1)
 * 3. Attempt to list posts with negative limit (limit: -10)
 * 4. Attempt to list posts with limit = 0 (invalid, as minimum is 1)
 * 5. Attempt to list posts with excessively large page number (page: 10_000_000)
 * 6. Attempt to list posts with excessively large limit (limit: 10_000_000)
 * 7. For all, confirm error messages are present and no post data is returned
 */
export async function test_api_post_list_with_invalid_pagination_parameters(connection: api.IConnection): Promise<void> {
  // 1. Negative page
  await TestValidator.httpError("Negative page is not allowed")(400)(() =>
    api.functional.posts.posts.patch(connection, {
      body: {
        page: -1 as number,
        limit: 10,
      } satisfies IPost.IRequest,
    })
  );

  // 2. Zero page
  await TestValidator.httpError("Zero page is not allowed")(400)(() =>
    api.functional.posts.posts.patch(connection, {
      body: {
        page: 0 as number,
        limit: 10,
      } satisfies IPost.IRequest,
    })
  );

  // 3. Negative limit
  await TestValidator.httpError("Negative limit is not allowed")(400)(() =>
    api.functional.posts.posts.patch(connection, {
      body: {
        page: 1,
        limit: -10 as number,
      } satisfies IPost.IRequest,
    })
  );

  // 4. Zero limit
  await TestValidator.httpError("Zero limit is not allowed")(400)(() =>
    api.functional.posts.posts.patch(connection, {
      body: {
        page: 1,
        limit: 0 as number,
      } satisfies IPost.IRequest,
    })
  );

  // 5. Excessively large page number
  await TestValidator.httpError("Excessively large page number should not be accepted")(400, 422)(() =>
    api.functional.posts.posts.patch(connection, {
      body: {
        page: 10_000_000,
        limit: 10,
      } satisfies IPost.IRequest,
    })
  );

  // 6. Excessively large limit number
  await TestValidator.httpError("Excessively large limit should not be accepted")(400, 422)(() =>
    api.functional.posts.posts.patch(connection, {
      body: {
        page: 1,
        limit: 10_000_000,
      } satisfies IPost.IRequest,
    })
  );
}

