/**
 * Validate that an author can retrieve the full details of their own post by ID.
 *
 * This test confirms that, after creating a user (the author), a category, and a post assigned to that user and category, the author can retrieve the post by its ID and see all allowed fields, such as title, content, category, and timestamps. It ensures no restricted fields are leaked and that all field values match what was created.
 *
 * Scenario steps:
 * 1. Register a user to act as the author
 * 2. Create a category to assign the post to
 * 3. Create a post authored by the registered user in the created category
 * 4. Retrieve the post by its ID as the author
 * 5. Validate that all post details match and that no restricted fields are leaked
 */
export async function test_api_post_details_author_retrieval(connection: api.IConnection): Promise<void> {
  // 1. Register a new user (author)
  const userRoleId = typia.random<string & tags.Format<"uuid">>(); // assume a valid existing roleId, or could look up a default role if available
