/**
 * Validate visibility of deleted post details for different roles.
 *
 * This test ensures that after soft-deleting a post, only administrators are able to access its full details, while normal users are denied access. The process involves creating two users (one normal, one admin), establishing a category, creating and deleting a post, and then ensuring correct permission behavior on post detail retrieval.
 *
 * 1. Register a normal user (member role)
 * 2. Register an admin user (administrator role)
 * 3. Create a category (as admin)
 * 4. Admin creates a post in the category
 * 5. Admin deletes the post (soft delete)
 * 6. Admin tries to get the deleted post's details (should succeed)
 * 7. Normal user tries to get the deleted post's details (should fail with 404 or forbidden)
 */
export async function test_api_post_deleted_post_details_admin_vs_user(connection: api.IConnection): Promise<void> {
  // 1. Register a normal user (member role)
  const memberRole = {
    id: crypto.randomUUID(),
    name: "member",
    description: "Regular community member"
  } satisfies IUserRole;
  const adminRole = {
    id: crypto.randomUUID(),
    name: "administrator",
    description: "Site administrator with full permissions"
  } satisfies IUserRole;

  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: memberRole.id,
      username: "testuser_" + Math.random().toString(36).substring(2),
      email: `user_` + Math.random().toString(36).substring(2) + `@test.com`,
      password: "Password123!",
      bio: "Normal member user",
      status: "active"
    } satisfies IUser.ICreate
  });
  typia.assert(user);

  // 2. Register an admin user (administrator role)
  const admin: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: adminRole.id,
      username: "admin_" + Math.random().toString(36).substring(2),
      email: `admin_` + Math.random().toString(36).substring(2) + `@test.com`,
      password: "AdminPassword123!",
      bio: "Administrator user",
      status: "active"
    } satisfies IUser.ICreate
  });
  typia.assert(admin);

  // 3. Create a category (as admin)
  const category: ICategory = await api.functional.core.categories.post(connection, {
    body: {
      name: "Announcements_" + Math.random().toString(36).substring(2, 8),
      description: "Test category for deleted post visibility"
    } satisfies ICategory.ICreate
  });
