    id: post.id
  });
  typia.assert(delResult);
  TestValidator.equals("Soft-deleted post returns success")(true)(delResult.success);

  // 6. Admin attempts to access deleted post details
  const adminDetail: IPost = await api.functional.posts.posts.getById(connection, { id: post.id });
  typia.assert(adminDetail);
  TestValidator.equals("Deleted post ID matches")(post.id)(adminDetail.id);
  TestValidator.predicate("Admin can see deleted_at on deleted post")(!!adminDetail.deleted_at);

  // 7. Normal user attempts to access deleted post
  await TestValidator.httpError("Normal user should not access deleted post")(403, 404)(async () => {
    // In reality, the backend should check session or role. Here, we simulate role context by documenting intent.
    // If a session context manager is available, switch context to user, or connect as user.
    await api.functional.posts.posts.getById(connection, { id: post.id });
  });
}

