import type { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";

export async function test_api_post_update_title_and_content_by_author(connection: api.IConnection): Promise<void> {
  /**
   * Test that an author can update the title and content of their own post successfully.
   *
   * This test validates the post update permission, field change policy, and audit field update behavior. An author registers, creates a category, then creates a post. The post is updated with new title and content, ensuring that restricted fields are not changed and the updated_at field reflects the modification.
   *
   * 1. Register a user (author)
   * 2. Create a new category
   * 3. Author creates a new post
   * 4. Author updates post title and content
   * 5. Validate that only permitted fields changed (title/content/updated_at), id/user_id/category_id remain unchanged
   * 6. Confirm updated_at is refreshed and all updates reflected in the response
   */

  // 1. Register a user
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: typia.random<string & tags.Format<"uuid">>(), // A random role or ideally use a fixed 'member' role
      username: `author_${Math.floor(Math.random()*1e5)}`,
      email: `author${Math.floor(Math.random()*1e7)}@wrtn.io`,
      bio: "Test author bio.",
      password: "password123!@#",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a category
  const category: ICategory = await api.functional.core.categories.post(connection, {
    body: {
      name: `cat_${Math.floor(Math.random()*1e7)}`,
      description: "E2E category for post update test.",
    } satisfies ICategory.ICreate,
  });
  typia.assert(category);

  // 3. Author creates a new post
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: category.id,
      title: "Original Post Title",
      content: "This is the first content of the post.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 4. Update the post (new title and content)
  const newTitle = "Updated Post Title";
  const newContent = "This is the updated content body.";
  const updated: IPost = await api.functional.posts.posts.putById(connection, {
    id: post.id,
    body: {
      title: newTitle,
      content: newContent,
    } satisfies IPost.IUpdate,
  });
  typia.assert(updated);

  // 5. Validate permitted field change only
  TestValidator.equals("ID should remain unchanged")(post.id)(updated.id);
  TestValidator.equals("Author ID remains unchanged")(post.user_id)(updated.user_id);
  TestValidator.equals("Category ID remains unchanged")(post.category_id)(updated.category_id);
  TestValidator.equals("Title updated")(newTitle)(updated.title);
  TestValidator.equals("Content updated")(newContent)(updated.content);

  // 6. Confirm updated_at is changed, created_at matches original
  TestValidator.equals("created_at untouched")(post.created_at)(updated.created_at);
  TestValidator.predicate("updated_at must be refreshed")(() => post.updated_at !== updated.updated_at);

  // 7. deleted_at is null and unchanged
  TestValidator.equals("deleted_at still null")(updated.deleted_at ?? null)(null);
}

