  await TestValidator.httpError("Forbidden to change category with existing comment(s)")(403)(() =>
    api.functional.posts.posts.putById(connection, {
      id: post.id,
      body: {
        category_id: categoryA.id,
      } satisfies IPost.IUpdate,
