/**
 * Validate that a post's original author can successfully delete their post (soft-delete).
 *
 * This scenario verifies that only the author can delete their own post via the posts API. Upon deletion, the post should no longer appear in normal listings but should remain in the database (soft-delete for audit). The API should return a proper success response, and database state should reflect the deletion (deleted_at populated).
 *
 * Steps:
 * 1. Register a user as the author (core.users.post)
 * 2. Create a category (core.categories.post)
 * 3. Author creates a post in this category (posts.posts.post)
 * 4. Author deletes the post (posts.posts.eraseById)
 * 5. Validate API success (`success: true` in IPost.IDeleteResult)
 * 6. (Assume existence of listing and lookup API) Check that the post doesn't appear in normal listing but remains retrievable by ID, with deleted_at populated.
 */
export async function test_api_post_author_erase_soft_delete_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register user (author)
  // For role, we use a hardcoded 'member' role UUID or test utility
  const userRoleId = typia.random<string & tags.Format<'uuid'>>(); // Replace with fixed value if required
  const authorRes: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: `user_${Math.random().toString(36).slice(2, 12)}`,
      email: `tester_${Math.random().toString(36).slice(2,8)}@mail.com`,
      bio: 'Board author',
      password: 'password1!',
      status: 'active',
    } satisfies IUser.ICreate,
  });
  typia.assert(authorRes);
  TestValidator.equals('user role match')(userRoleId)(authorRes.user_role_id);

  // 2. Create a category
  const categoryRes = await api.functional.core.categories.post(connection, {
    body: {
      name: `cat_${Math.random().toString(36).slice(2,10)}`,
      description: 'Category for post deletion test',
    } satisfies ICategory.ICreate,
  });
  typia.assert(categoryRes);

  // 3. Author creates a post
  const postRes = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: categoryRes.id,
      title: 'Post to be deleted',
      content: 'This post will be tested for soft delete by author.',
      user_id: authorRes.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postRes);
  TestValidator.equals('Author should match')(authorRes.id)(postRes.user_id);
  TestValidator.equals('Category should match')(categoryRes.id)(postRes.category_id);
  TestValidator.equals('deleted_at should initially be missing')(postRes.deleted_at ?? null)(null);

  // 4. Author deletes the post
  const delResult = await api.functional.posts.posts.eraseById(connection, {
    id: postRes.id,
  });
  typia.assert(delResult);
  TestValidator.equals('delete API success')(true)(delResult.success);

  // 5. (Extra) Validate DB state: Fetch post to check deleted_at populated
  // (Assuming there exists posts.posts.at or similar. Otherwise skip this check.)
  // const fetched = await api.functional.posts.posts.at(connection, { id: postRes.id });
  // typia.assert(fetched);
  // TestValidator.predicate('Post should have deleted_at set')(() => !!fetched.deleted_at);
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import type { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";

/**
 * Attempt to delete a post with active comments should be denied.
 *
 * This test verifies the business rule that prevents deletion of posts which already have active comments.
 * A user is registered, a category is created, a post is authored, and a comment is added to it.
 * Then, an attempt to delete that post is made. The API should block this action, responding with an appropriate error message and leaving the post (and its comment) intact.
 *
 * Steps:
 * 1. Register a user for posting.
 * 2. Create a category for post assignment.
 * 3. Create a post assigned to that user & category.
 * 4. Add an active comment to the post.
 * 5. Attempt to delete the post.
 * 6. Verify API blocks deletion with a clear error, and data remains unaffected.
 */
export async function test_api_post_delete_post_with_active_comments_denied(connection: api.IConnection): Promise<void> {
  // 1. Register user
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: typia.random<string & tags.Format<"uuid">>(),
      username: `active-comment-poster-${Date.now()}`,
      email: `test-delete-comment-${Date.now()}@wrtn.io`,
      bio: "Post author for comment-delete scenario.",
      password: "securepw123!",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create category
  const category: ICategory = await api.functional.core.categories.post(connection, {
    body: {
      name: `ScenarioCategory-${Date.now()}`,
      description: "Test category for delete-with-comment-deny-test.",
    } satisfies ICategory.ICreate,
  });
  typia.assert(category);

  // 3. Create post
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      user_id: user.id,
      category_id: category.id,
      title: "Cannot delete me if commented!",
      content: "Attempting to delete this post must fail if it has comments.",
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 4. Add an active comment
  const comment: IComment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      content: "This is an active comment, should prevent post deletion.",
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("Comment's post matches post")(post.id)(comment.post_id);

  // 5. Attempt to delete the post (should be denied by business rule)
  await TestValidator.httpError("Cannot delete post with active comments")(409)(() =>
    api.functional.posts.posts.eraseById(connection, {
      id: post.id,
    }),
  );

  // 6. (Optional) Verify post and comment remain.
  // If GET endpoints are available for posts and comments, they should be checked here. For now, this step is conceptual.
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import type { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";

/**
 * Attempt to delete a post as a user who is not the author.
 *
 * This test validates the permissions model on post deletion: non-authors should not be allowed to delete posts. The scenario ensures that a delete attempt by a user who is not the original author results in a forbidden error, and the post remains unaffected in the system. Only the original author or privileged users (such as moderators or admins) may perform deletion actions.
 *
 * Steps:
 * 1. Register an author user.
 * 2. Register a non-author user.
 * 3. Create a category.
 * 4. Author user creates a post in that category.
 * 5. Non-author user attempts to delete the post → Should receive a forbidden error (HTTP 403).
 * 6. Confirm that the post still exists and is not marked as deleted in the database.
 * 7. (Optionally) Delete with the author user or privileged role to confirm the only allowed path to deletion.
 */
export async function test_api_post_delete_post_by_non_author_forbidden(connection: api.IConnection): Promise<void> {
  // 1. Register an author user
  const authorRoleId = typia.random<string & tags.Format<"uuid">>();
  const nonAuthorRoleId = typia.random<string & tags.Format<"uuid">>();
  const authorUser: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: authorRoleId,
      username: `author_${Date.now()}`,
      email: `author_${Date.now()}@test.com`,
      password: "author_password",
      status: "active"
    } satisfies IUser.ICreate,
  });
  typia.assert(authorUser);

  // 2. Register a non-author user
  const nonAuthorUser: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: nonAuthorRoleId,
      username: `nonauthor_${Date.now()}`,
      email: `nonauthor_${Date.now()}@test.com`,
      password: "nonauthor_password",
      status: "active"
    } satisfies IUser.ICreate,
  });
  typia.assert(nonAuthorUser);

  // 3. Create a category
  const category: ICategory = await api.functional.core.categories.post(connection, {
    body: {
      name: `category_${Date.now()}`,
      description: "Test category for permission validation."
    } satisfies ICategory.ICreate
  });
  typia.assert(category);

  // 4. Author user creates a post
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: category.id,
      title: `Test Post ${Date.now()}`,
      content: "This post is for delete permission checking.",
      user_id: authorUser.id
    } satisfies IPost.ICreate
  });
  typia.assert(post);

  // 5. Non-author tries to delete the post
  await TestValidator.httpError("Non-author cannot delete post")(403)(() =>
    api.functional.posts.posts.eraseById(connection, {
      id: post.id,
      // (normally, session would authenticate as non-author; simulation for now)
    })
  );

  // 6. Confirm the post still exists and not marked as deleted
  const reloadedPost: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: category.id,
      title: post.title,
      content: post.content,
      user_id: authorUser.id
    } satisfies IPost.ICreate
  });
  typia.assert(reloadedPost);
  TestValidator.equals("Post ID unchanged")(post.id)(reloadedPost.id);
  TestValidator.equals("Post deleted_at should be null or undefined")(reloadedPost.deleted_at ?? null)(null);

  // 7. (Optionally) Confirm that original author can delete (depends on API logic)
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import type { IPageIVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a paginated and filtered list of votes for a specific user.
 *
 * This scenario validates the following:
 * - Only the user's own votes (or admin viewing any user's votes) can be listed.
 * - Proper functioning of pagination (limit/offset), and checking count boundaries.
 * - Filtering by post and comment ids is effective and returns only matching votes.
 * - The edge case where no votes exist for given filter/pagination criteria is handled: data is empty, but pagination meta is consistent.
 * - Forbidden access: normal users cannot request votes belonging to other users; only admins can.
 *
 * Steps:
 * 1. Create two users: Alice (ordinary) and Bob (ordinary).
 * 2. Create another admin user.
 * 3. Have Alice create a post.
 * 4. Both Alice and Bob vote on Alice's post.
 * 5. List votes as Alice, filter by her own userId: Alice should see her own vote, not Bob's.
 * 6. List votes as Bob, filter by his own userId: Bob sees only his own vote.
 * 7. Paginate: vote with limit=1, offset=0 as Alice; then offset=1. Counts must match.
 * 8. Filter by postId: both Alice and Bob list votes for the post (using their own userId in the filter). Ensure correct vote returned by each.
 * 9. Filter by non-existent post/comment id: expects empty data but correct pagination meta.
 * 10. Bob tries to list Alice's votes: forbidden (no access).
 * 11. Admin lists Alice's votes by her userId: sees only Alice's votes.
 */
export async function test_api_vote_list_votes_by_user_with_pagination_and_filters(connection: api.IConnection): Promise<void> {
  // 1. Create user roles for member and admin.
  // Assume roles exist with known UUIDs: 'memberRoleId' and 'adminRoleId'.
  const memberRoleId = "00000000-0000-4000-8000-000000000001" as string & tags.Format<"uuid">;
  const adminRoleId = "00000000-0000-4000-8000-000000000002" as string & tags.Format<"uuid">;

  // 2. Create Alice (ordinary), Bob (ordinary), and Admin users
  const alice = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: memberRoleId,
      username: "alice",
      email: `alice.${Date.now()}@example.com`,
      password: "alicepw",
      status: "active",
      bio: "Alice's bio",
    } satisfies IUser.ICreate,
  });
  typia.assert(alice);

  const bob = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: memberRoleId,
      username: "bob",
      email: `bob.${Date.now()}@example.com`,
      password: "bobpw",
      status: "active",
      bio: "Bob's bio",
    } satisfies IUser.ICreate,
  });
  typia.assert(bob);

  const admin = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: adminRoleId,
      username: "adminuser",
      email: `admin.${Date.now()}@example.com`,
      password: "adminpw",
      status: "active",
      bio: "The admin",
    } satisfies IUser.ICreate,
  });
  typia.assert(admin);

  // 3. Alice creates a post
  const alicePost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: "00000000-0000-4000-8000-000000000099" as string & tags.Format<"uuid">, // assume exists
      title: `Alice's Test Post ${Date.now()}`,
      content: "Test content for voting.",
      user_id: alice.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(alicePost);

  // 4. Both Alice and Bob vote on Alice's post
  const aliceVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: alice.id,
      post_id: alicePost.id,
      value: +1,
    } satisfies IVote.ICreate,
  });
  typia.assert(aliceVote);

  const bobVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: bob.id,
      post_id: alicePost.id,
      value: -1,
    } satisfies IVote.ICreate,
  });
  typia.assert(bobVote);

  // 5. List votes as Alice, filter by her own userId
  let votes = await api.functional.votes.votes.patch(connection, {
    body: {
      userId: alice.id,
    } satisfies IVote.IRequest,
  });
  typia.assert(votes);
  TestValidator.predicate("Only Alice's votes are returned")(() =>
    votes.data.every(v => v.user_id === alice.id),
  );

  // 6. List votes as Bob, filter by his own userId
  votes = await api.functional.votes.votes.patch(connection, {
    body: {
      userId: bob.id,
    } satisfies IVote.IRequest,
  });
  typia.assert(votes);
  TestValidator.predicate("Only Bob's votes are returned")(() =>
    votes.data.every(v => v.user_id === bob.id),
  );

  // 7. Pagination check (as Alice): limit=1, offset=0 then offset=1
  let pagedVotes = await api.functional.votes.votes.patch(connection, {
    body: { userId: alice.id, limit: 1, offset: 0 } satisfies IVote.IRequest,
  });
  typia.assert(pagedVotes);
  TestValidator.equals("Page contains at most 1 result")(true)(pagedVotes.data.length <= 1);
  // Try with offset=1 for Alice (expect possibly empty or counts decrease)
  const pagedVotes2 = await api.functional.votes.votes.patch(connection, {
    body: { userId: alice.id, limit: 1, offset: 1 } satisfies IVote.IRequest,
  });
  typia.assert(pagedVotes2);
  TestValidator.equals("Page contains at most 1 result")(true)(pagedVotes2.data.length <= 1);
  TestValidator.equals("Pagination structure is consistent")(pagedVotes.pagination.limit)(pagedVotes2.pagination.limit);

  // 8. Filter by postId: Alice should get her vote, Bob gets his
  const alicePostVotes = await api.functional.votes.votes.patch(connection, {
    body: { userId: alice.id, postId: alicePost.id } satisfies IVote.IRequest,
  });
  typia.assert(alicePostVotes);
  TestValidator.predicate("Vote returned matches Alice and post")(() =>
    alicePostVotes.data.every(
      v => v.user_id === alice.id && v.post_id === alicePost.id,
    ),
  );

  const bobPostVotes = await api.functional.votes.votes.patch(connection, {
    body: { userId: bob.id, postId: alicePost.id } satisfies IVote.IRequest,
  });
  typia.assert(bobPostVotes);
  TestValidator.predicate("Vote returned matches Bob and post")(() =>
    bobPostVotes.data.every(
      v => v.user_id === bob.id && v.post_id === alicePost.id,
    ),
  );

  // 9. Filter with non-existent postId/commentId
  const notFoundVotes = await api.functional.votes.votes.patch(connection, {
    body: {
      userId: alice.id,
      postId: "00000000-0000-4000-8000-999999999999" as string & tags.Format<"uuid">,
    } satisfies IVote.IRequest,
  });
  typia.assert(notFoundVotes);
  TestValidator.equals("Empty votes array for non-existent post")([] as IVote.ISummary[])(notFoundVotes.data);
  TestValidator.equals("Pagination meta counts 0")(
    0 as number & tags.Type<"int32">,
  )(notFoundVotes.pagination.records);

  // 10. Bob tries to list Alice's votes: forbidden (should throw or error)
  await TestValidator.httpError("Bob cannot see Alice's votes")(403)(() =>
    api.functional.votes.votes.patch(connection, {
      body: {
        userId: alice.id,
      } satisfies IVote.IRequest,
    }),
  );

  // 11. Admin lists Alice's votes by her userId: permitted, only Alice's votes returned
  const adminVotes = await api.functional.votes.votes.patch(connection, {
    body: { userId: alice.id } satisfies IVote.IRequest,
  });
  typia.assert(adminVotes);
  TestValidator.predicate("Admin receives only Alice's votes")(() =>
    adminVotes.data.every(v => v.user_id === alice.id),
  );
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import type { IPageIVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate error responses on votes list API with invalid query parameters.
 *
 * This test checks that the pagination, sorting, and filter business rules on the votes list endpoint
 * produce proper HTTP errors when given invalid inputs. This includes negative page or limit, an invalid sort field,
 * and the forbidden combination of both postId and commentId filters.
 *
 * 1. Supply a negative limit (should error)
 * 2. Supply a negative offset (should error)
 * 3. Supply an invalid sort field (should error)
 * 4. Supply both postId and commentId (should error)
 */
export async function test_api_vote_list_votes_with_invalid_query_parameters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Negative limit
  await TestValidator.httpError("votes list: negative limit must fail")(400)(() =>
    api.functional.votes.votes.patch(connection, {
      body: {
        limit: -5,
      } satisfies IVote.IRequest,
    }),
  );

  // 2. Negative offset
  await TestValidator.httpError("votes list: negative offset must fail")(400)(() =>
    api.functional.votes.votes.patch(connection, {
      body: {
        offset: -10,
      } satisfies IVote.IRequest,
    }),
  );

  // 3. Invalid sort field
  await TestValidator.httpError("votes list: invalid sort field must fail")(400)(() =>
    api.functional.votes.votes.patch(connection, {
      body: {
        sort: "not-a-real-field:desc",
      } satisfies IVote.IRequest,
    }),
  );

  // 4. Both postId and commentId supplied
  await TestValidator.httpError("votes list: both postId and commentId forbidden")(400)(() =>
    api.functional.votes.votes.patch(connection, {
      body: {
        postId: "00000000-0000-0000-0000-000000000011",
        commentId: "00000000-0000-0000-0000-000000000022",
      } satisfies IVote.IRequest,
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Validate end-to-end: user can retrieve the details of their own vote by ID.
 *
 * This scenario covers the process whereby a user:
 * 1. Registers as a new user (for authentication and as vote actor)
 * 2. Creates a post as the target for voting
 * 3. Casts a vote (up or down) on that post
 * 4. Retrieves the vote details by its ID
 * 5. Confirms that the retrieved vote matches the creation data (including all system-generated fields)
 * 6. Verifies that secret or system-only fields are not leaked
 * 7. Logs vote retrieval for audit traceability
 */
export async function test_api_vote_retrieve_vote_detail_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new user
  const roleId = typia.random<string & tags.Format<"uuid">>(); // For testing, typically 'member'
  const userData: IUser.ICreate = {
    user_role_id: roleId,
    username: `tester_${Math.random().toString(36).substring(2,8)}`,
    email: `tester_${Math.random().toString(36).substring(2,10)}@test.dev`,
    password: "1234test$",
    bio: "Just a voting test user.",
    status: "active"
  };
  const user: IUser = await api.functional.core.users.post(connection, { body: userData });
  typia.assert(user);
  TestValidator.equals("username")(userData.username)(user.username);
  TestValidator.equals("email matches")(userData.email)(user.email);
  TestValidator.equals("role id matches")(userData.user_role_id)(user.user_role_id);

  // 2. Create a post (with this user as author)
  const postData: IPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Vote Target Post",
    content: "For voting scenario test",
    user_id: user.id
  };
  const post: IPost = await api.functional.posts.posts.post(connection, { body: postData });
  typia.assert(post);
  TestValidator.equals("Post title matches")(postData.title)(post.title);
  TestValidator.equals("Author matches")(user.id)(post.user_id);

  // 3. User votes on the post
  const voteCreate: IVote.ICreate = {
    user_id: user.id,
    value: 1,
    post_id: post.id,
    comment_id: null
  };
  const vote: IVote = await api.functional.votes.votes.post(connection, { body: voteCreate });
  typia.assert(vote);
  TestValidator.equals("Voter user matches")(user.id)(vote.user_id);
  TestValidator.equals("Vote value matches")(voteCreate.value)(vote.value);
  TestValidator.equals("Vote post matches")(vote.post_id)(post.id);
  TestValidator.equals("Vote comment is null")(vote.comment_id)(null);

  // 4. Retrieve the vote by its ID (as the owner)
  const retrieved: IVote = await api.functional.votes.votes.getById(connection, { id: vote.id });
  typia.assert(retrieved);
  TestValidator.equals("vote ID matches")(vote.id)(retrieved.id);
  TestValidator.equals("user id matches")(user.id)(retrieved.user_id);
  TestValidator.equals("post id matches")(retrieved.post_id)(post.id);
  TestValidator.equals("comment_id matches")(retrieved.comment_id)(null);
  TestValidator.equals("vote value matches")(vote.value)(retrieved.value);

  // 5. Check no sensitive/system-only fields are exposed
  // IVote interface has no confidential fields: id, user_id, post_id/comment_id, value, created_at.
  // So we ensure only those fields are present.
  const allowed = ["id", "user_id", "post_id", "comment_id", "value", "created_at"];
  for (const k of Object.keys(retrieved)) {
    TestValidator.predicate(`field '${k}' must be allowed`)(() => allowed.includes(k));
  }
}

