import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Validate vote creation with missing or invalid fields.
 *
 * This test ensures the system properly rejects all malformed or unauthorized vote creation attempts, including:
 * - Missing required fields (no 'value', no 'postId' or 'commentId')
 * - Invalid 'value' (not +1 or -1)
 * - Both 'postId' and 'commentId' supplied together
 * - Referencing non-existing post or comment
 * - Unauthorized (non-user) attempting vote
 *
 * Each attempt must yield an error and no vote record should be created.
 *
 * 1. Attempt vote creation without 'value' (required field missing)
 * 2. Attempt vote creation without target (neither 'postId' nor 'commentId')
 * 3. Attempt with both 'postId' and 'commentId' supplied
 * 4. Attempt with invalid 'value' field (not +1 or -1)
 * 5. Attempt referencing a non-existent 'postId'
 * 6. Attempt referencing a non-existent 'commentId'
 * 7. Attempt vote creation as unauthorized user (not logged in)
 */
export async function test_api_vote_create_vote_missing_or_invalid_fields(connection: api.IConnection): Promise<void> {
  // 1. Attempt vote creation without 'value' (missing required field)
  const baseVote = {
    user_id: "d011bcae-7c3a-4cd9-bb4b-cda8d0091111", // suppose a valid user
    post_id: "9890e201-fc0e-47e8-9df5-17a494a31111", // suppose a valid post
  };
  await TestValidator.httpError("missing value")(400)(() =>
    api.functional.votes.votes.post(connection, {
      body: { ...baseVote } as any, // omitting value
    })
  );

  // 2. Attempt vote creation without target (neither postId nor commentId)
  await TestValidator.httpError("missing both postId and commentId")(400)(() =>
    api.functional.votes.votes.post(connection, {
      body: {
        user_id: baseVote.user_id,
        value: +1,
      } as any, // No postId/commentId
    })
  );

  // 3. Attempt both postId and commentId supplied (mutually exclusive)
  await TestValidator.httpError("both postId and commentId supplied")(400)(() =>
    api.functional.votes.votes.post(connection, {
      body: {
        user_id: baseVote.user_id,
        value: +1,
        post_id: baseVote.post_id,
        comment_id: "574a1540-edeb-4fd5-8888-b108b4a81111",
      },
    })
  );

  // 4. Invalid 'value' field (not +1 or -1)
  for (const invalid of [0, 2, -2, 99, -99]) {
    await TestValidator.httpError("vote value not +1/-1")(400)(() =>
      api.functional.votes.votes.post(connection, {
        body: {
          user_id: baseVote.user_id,
          value: invalid,
          post_id: baseVote.post_id,
        },
      })
    );
  }

  // 5. Non-existent postId
  await TestValidator.httpError("non-existent postId")(404)(() =>
    api.functional.votes.votes.post(connection, {
      body: {
        user_id: baseVote.user_id,
        value: +1,
        post_id: "00000000-0000-4000-8000-000000000000", // unlikely to exist
      },
    })
  );
  // 6. Non-existent commentId
  await TestValidator.httpError("non-existent commentId")(404)(() =>
    api.functional.votes.votes.post(connection, {
      body: {
        user_id: baseVote.user_id,
        value: +1,
        comment_id: "00000000-0000-4000-8000-000000000001", // unlikely to exist
      },
    })
  );
  // 7. Attempt as unauthorized user
  await TestValidator.httpError("unauthorized vote creation")(401, 403)(() =>
    api.functional.votes.votes.post({ ...connection, headers: {} }, {
      body: {
        user_id: baseVote.user_id,
        value: +1,
        post_id: baseVote.post_id,
      },
    })
  );
}

