/**
 * Test a user successfully updates their own vote's value (e.g., upvote to downvote).
 *
 * This scenario validates the ability for a user to change their vote value on a post, such as switching from an upvote to a downvote. It ensures both value updating and immutability of vote's target references (postId/commentId). All objects must be linked in the correct order.
 *
 * 1. Create a user
 * 2. Create a post (as that user)
 * 3. Create an initial vote on the post (by that user, value +1)
 * 4. Update the vote (change value from +1 to -1)
 * 5. Response should reflect updated value and unchanged postId/commentId
 */
export async function test_api_vote_update_vote_value_successful(connection: api.IConnection): Promise<void> {
  // 1. Create user
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const username = "vote_tester_" + Math.floor(Math.random() * 10_000_000);
  const email = username + "@test.com";
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username,
      email,
      bio: "test voter",
      password: "testpass1!",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create post
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Vote Target Post",
      content: "A post to be voted on.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 3. Create initial vote on the post
  const vote: IVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: user.id,
      value: 1,
      post_id: post.id,
    } satisfies IVote.ICreate,
  });
  typia.assert(vote);
  TestValidator.equals("Vote user match")(user.id)(vote.user_id);
  TestValidator.equals("Vote post match")(vote.post_id ?? null)(post.id);
  TestValidator.equals("Initial value +1")(1)(vote.value);

  // 4. Update vote value (flip from +1 to -1)
  const updatedVote: IVote = await api.functional.votes.votes.putById(connection, {
    id: vote.id,
    body: {
      value: -1,
    } satisfies IVote.IUpdate,
  });
  typia.assert(updatedVote);

  // 5. Validation
  TestValidator.equals("Vote id is unchanged")(vote.id)(updatedVote.id);
  TestValidator.equals("Vote user is unchanged")(vote.user_id)(updatedVote.user_id);
  TestValidator.equals("Vote postId is unchanged")(vote.post_id ?? null)(updatedVote.post_id ?? null);
  TestValidator.equals("Vote commentId is unchanged")(vote.comment_id ?? null)(updatedVote.comment_id ?? null);
  TestValidator.equals("Vote value updated to -1")(-1)(updatedVote.value);
}

