 *
 * Ensures business rule: Only the 'value' of a vote may be updated; attempts to change target (postId/commentId) are rejected.
 *
 * 1. Register a user
 * 2. Create a post for voting
 * 3. Create a vote on the post by the user
 * 4. Attempt to update the vote, trying to change both value and the postId (to a different post)
 * 5. Confirm update is rejected (validation/forbidden error)
 * 6. Target association for the vote is not changed
 */
export async function test_api_vote_update_immutable_fields_error(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a user
  const user = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: "member-role-uuid-placeholder",
      username: `test_vote_immutable_${Date.now()}`,
      email: `test_vote_immutable_${Date.now()}@test.com`,
      password: "password123",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a post for voting
  const post = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: "category-uuid-placeholder",
      title: `Immutable vote post ${Date.now()}`,
      content: "Testing immutable vote post reference.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a vote on the post by the user
  const vote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: user.id,
      value: 1,
      post_id: post.id,
    } satisfies IVote.ICreate,
  });
  typia.assert(vote);

  // 4. Attempt to update immutable fields (e.g., post_id) via PUT /votes/votes/:id
  // We'll try to specify post_id again in the update body (which is only allowed to include 'value')
  // Since the SDK and type-safe routes only allow 'value': number, simulate sending an illegal request structure to demonstrate rejection.
  // We'll also try to update value and attempt an update with illegal structure.

  // a) Try directly illegal structure (simulation, will fail at compile-time, skip)
  // b) Try a legal update with 'value' field - should succeed
  const updated = await api.functional.votes.votes.putById(connection, {
    id: vote.id,
    body: {
      value: -1,
    } satisfies IVote.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("Vote value changed to -1")(-1)(updated.value);
  TestValidator.equals("Vote association unchanged")(updated.post_id)(post.id);

  // c) Try using any-casting to attempt forbidden update
  await TestValidator.httpError("Should reject patching post_id on update")(400, 403)(() =>
    api.functional.votes.votes.putById(connection, {
      id: vote.id,
      body: Object.assign({ value: -1, post_id: "forbidden-uuid-change" }, {}) as any, // purposely using 'any' to bypass type
    }),
  );
}

