import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Test negative deletion cases for votes: only owner or privileged user may delete.
 *
 * Scenario ensures that:
 * - Deleting a vote as a non-owner fails (forbidden)
 * - Deleting a vote unauthenticated fails (forbidden or unauthorized)
 * - Deleting a non-existent vote returns not found/error
 * - No accidental deletion occurs in these failure cases
 *
 * Process:
 * 1. Register two users: 'owner' (will cast the vote), and 'intruder'
 * 2. Owner creates a post
 * 3. Owner casts a vote on their post
 * 4. Intruder attempts to delete owner's vote (expect 403 Forbidden)
 * 5. Unauthenticated deletion attempt (expect 401 Unauthorized or 403)
 * 6. Attempt to delete a non-existent vote (expect 404 Not Found)
 * 7. Confirm owner's vote is still present after failed deletions
 */
export async function test_api_vote_delete_unauthorized_or_nonexistent(connection: api.IConnection): Promise<void> {
  // 1. Register owner user
  const owner = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: typia.random<string & tags.Format<"uuid">>(),
      username: `owner_${Date.now()}`,
      email: `owner_${Date.now()}@test.com`,
      password: "testpassword",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(owner);

  // 2. Register intruder user
  const intruder = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: typia.random<string & tags.Format<"uuid">>(),
      username: `intruder_${Date.now()}`,
      email: `intruder_${Date.now()}@test.com`,
      password: "testpassword",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(intruder);

  // 3. Owner creates a post
  const post = await api.functional.posts.posts.post(connection, {
    body: {
      user_id: owner.id,
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Vote Protection Test Post",
      content: "Test for unauthorized deletion of votes.",
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 4. Owner casts a vote on their post
  const vote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: owner.id,
      value: 1,
      post_id: post.id,
    } satisfies IVote.ICreate,
  });
  typia.assert(vote);

  // 5. Try delete as intruder (should fail: 403)
  // Switch to 'intruder' session if applicable (simulate auth context)
  let intruderConn = { ...connection, headers: { ...(connection.headers ?? {}), "X-USER-ID": intruder.id } };
  await TestValidator.httpError("Non-owner cannot delete vote")(403)(() =>
    api.functional.votes.votes.eraseById(intruderConn, { id: vote.id })
  );

  // 6. Try delete unauthenticated (should fail: 401 or 403)
  let anonConn = { ...connection, headers: { ...((connection.headers??{})), } };
  delete anonConn.headers["X-USER-ID"];
  await TestValidator.httpError("Unauthenticated cannot delete vote")(401, 403)(() =>
    api.functional.votes.votes.eraseById(anonConn, { id: vote.id })
  );

  // 7. Try deleting a non-existent vote (should fail: 404)
  const fakeVoteId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("Deleting non-existent vote fails")(404)(() =>
    api.functional.votes.votes.eraseById({ ...connection, headers: { ...(connection.headers??{}), "X-USER-ID": owner.id } }, {
      id: fakeVoteId,
    })
  );

  // 8. Confirm owner's vote is still present (by attempting delete as owner -- should succeed)
  const ok = await api.functional.votes.votes.eraseById({ ...connection, headers: { ...(connection.headers??{}), "X-USER-ID": owner.id } },
    { id: vote.id }
  );
  typia.assert(ok); // Should succeed
  TestValidator.equals("Should be deleted now and deleted:true")(true)(ok.deleted);
}

