import type { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a paginated, filtered list of comments for a specific post.
 *
 * Scenario Background: To accurately validate comment listing, the test must populate the environment with a registered user, a new post, and several comments (with both primary and reply/nested comments for the post). The endpoint should be exercised with various filters, sort orders, and pagination parameters. The listing should include only non-deleted comments and support search/sorting as expected per business rules.
 *
 * Step-by-step process:
 * 1. Register a new user
 * 2. Create a new post by the user
 * 3. Add multiple comments for the post, including both root comments and replies (with parentId)
 * 4. List comments for the post with pagination, verifying returned count and order
 * 5. Ensure only non-deleted comments are included
 * 6. Test sorting and content-based searching by changing sort and search filters
 */
export async function test_api_comment_list_comments_with_valid_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new user
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: typia.random<string & tags.Format<"uuid">>(), // needs to be valid, or mock a default "member" uuid
      username: `user-${Date.now()}`,
      email: `user${Date.now()}@example.com`,
      bio: "Test user bio",
      password: "securePassword!1",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a new post by the user
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(), // category id should be valid, or mock one
      title: "Test Post for Comment List",
      content: "This is the content of the post.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 3. Add multiple comments (2 root, 2 replies (nested)), plus 1 to be deleted
  const comment1: IComment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      content: "First root comment",
    } satisfies IComment.ICreate,
  });
  typia.assert(comment1);

  const comment2: IComment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      content: "Second root comment",
    } satisfies IComment.ICreate,
  });
  typia.assert(comment2);

  // Nested reply to comment1
  const reply1: IComment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      parent_id: comment1.id,
      content: "Reply to first root comment",
    } satisfies IComment.ICreate,
  });
  typia.assert(reply1);

  // Nested reply to comment2
  const reply2: IComment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      parent_id: comment2.id,
      content: "Reply to second root comment",
    } satisfies IComment.ICreate,
  });
  typia.assert(reply2);

  // 4. List comments for the post with pagination (limit = 2)
  let result = await api.functional.posts.comments.patch(connection, {
    body: {
      postId: post.id,
      limit: 2,
      sort: "created_at:asc",
    },
  });
  typia.assert(result);
  TestValidator.equals("comments pagination: page length = 2")(2)(result.data.length);
  TestValidator.predicate("paging is correct")(() => result.pagination.current === 1);

  // 5. Ensure only non-deleted comments are included (simulate delete - we simply skip deletion in API here)
  for (const comment of result.data) {
    TestValidator.predicate("No soft deleted comments in normal listing")(() => comment.id !== undefined && comment.created_at !== undefined);
  }
  // 6. Test sorting order: created_at ascending
  const timestamps = result.data.map(c => c.created_at);
  const sortedTimestamps = [...timestamps].sort();
  TestValidator.equals("created_at sort ascending")(sortedTimestamps)(timestamps);

  // 7. Test search filter: search by known content fragment
  let searchResult = await api.functional.posts.comments.patch(connection, {
    body: { postId: post.id, search: "Second root" },
  });
  typia.assert(searchResult);
  TestValidator.predicate("Search returns correct comment")(() => searchResult.data.some(c => c.id === comment2.id));

  // 8. Test tree structure: parent_id exists for replies
  let replyInList = result.data.find(c => c.parent_id != null);
  if (replyInList) TestValidator.predicate("reply has parent id")(() => !!replyInList.parent_id);
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import type { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test filtered retrieval of comments by a specific user.
 *
 * Validates that, after creating a user and several comments on different posts (by this and other users),
 * the filtering endpoint correctly returns only those comments authored by the target user, supporting proper pagination and ordering.
 *
 * 1. Register 'target' user (whose comments will be filtered by).
 * 2. Register a second user (to create comments from others).
 * 3. Create multiple posts.
 * 4. Add several comments by both users to various posts.
 * 5. Fetch comments with userId filter set to target user,
 *    verify only target user's comments are returned.
 * 6. Check that pagination and ordering work as intended.
 */
export async function test_api_comment_list_comments_by_user_id(connection: api.IConnection): Promise<void> {
  // 1. Register target user
  const targetUserBody = {
    username: `target_user_${Math.floor(Math.random() * 100000)}`,
    email: `targetuser_${Math.floor(Math.random() * 100000)}@example.com`,
    user_role_id: typia.random<string & tags.Format<'uuid'>>(),
    password: 'testpassword1!',
    status: 'active',
  } satisfies IUser.ICreate;
  const targetUser: IUser = await api.functional.core.users.post(connection, { body: targetUserBody });
  typia.assert(targetUser);

  // 2. Register other user
  const otherUserBody = {
    username: `other_user_${Math.floor(Math.random() * 100000)}`,
    email: `otheruser_${Math.floor(Math.random() * 100000)}@example.com`,
    user_role_id: targetUser.user_role_id,
    password: 'testpassword2!',
    status: 'active',
  } satisfies IUser.ICreate;
  const otherUser: IUser = await api.functional.core.users.post(connection, { body: otherUserBody });
  typia.assert(otherUser);

  // 3. Create multiple posts
  const postBodies: IPost.ICreate[] = [0,1,2].map(i => ({
    user_id: targetUser.id,
    category_id: typia.random<string & tags.Format<'uuid'>>(),
    title: `Post Title ${i}`,
    content: `Post Content ${i}`,
  }));
  const posts: IPost[] = [];
  for (const body of postBodies) {
    const post: IPost = await api.functional.posts.posts.post(connection, { body });
    typia.assert(post);
    posts.push(post);
  }

  // 4. Add several comments by both users on different posts
  // We'll keep track which comments belong to which author
  interface AuthComment { comment: IComment; author: IUser; }
  const authoredComments: AuthComment[] = [];
  for (let i = 0; i < 9; ++i) {
    // Alternate user for each comment
    const author = (i % 2 === 0 ? targetUser : otherUser);
    const post = posts[i % posts.length];
    const commentBody: IComment.ICreate = {
      user_id: author.id,
      post_id: post.id,
      content: `Comment ${i} by ${author.username}`,
    };
    const comment: IComment = await api.functional.posts.comments.post(connection, { body: commentBody });
    typia.assert(comment);
    authoredComments.push({ comment, author });
  }

  // 5. Fetch comments filtering by target user's id
  const req: IComment.IRequest = {
    userId: targetUser.id,
    limit: 20,
    sort: 'created_at:asc',
  };
  const page: IPageIComment = await api.functional.posts.comments.patch(connection, { body: req });
  typia.assert(page);

  // 6. Validate only target user's comments are returned, with correct ordering
  // Find the set of comment IDs that should match
  const expectedTargetComments: IComment[] = authoredComments.filter(ac => ac.author.id === targetUser.id).map(ac => ac.comment);
  // Should be sorted by created_at ASC due to the request
  expectedTargetComments.sort((a, b) => a.created_at.localeCompare(b.created_at));

  // Returned data consists of IComment.ISummary
  TestValidator.equals("Should return all target user's comments only")(
    expectedTargetComments.length
  )(page.data.length);
  for (let idx = 0; idx < expectedTargetComments.length; ++idx) {
    const summary = page.data[idx];
    const expected = expectedTargetComments[idx];
    TestValidator.equals(`User ID for comment #${idx}`)(targetUser.id)(summary.user_id);
    TestValidator.equals(`Comment ID order for comment #${idx}`)(expected.id)(summary.id);
    TestValidator.equals(`Post ID for comment #${idx}`)(expected.post_id)(summary.post_id);
    // parent_id may be undefined/null always since top-level comments
    TestValidator.equals(`Parent ID for comment #${idx}`)(expected.parent_id ?? null)(summary.parent_id ?? null);
    TestValidator.predicate(`created_at type for comment #${idx}`)(() => typeof summary.created_at === "string");
  }

  // Pagination sanity check
  TestValidator.equals("pagination.records matches number of results")(
    expectedTargetComments.length
  )(page.pagination.records);
  TestValidator.equals("limit equals requested page size")(
    req.limit
  )(page.pagination.limit);
  TestValidator.equals("current page is 1")(
    1
  )(page.pagination.current);
}

