export async function test_api_comment_get_deleted_comment_as_admin(connection: api.IConnection): Promise<void> {
  // 1. Register admin user
  const adminUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: "admin-role-uuid", // replace with actual admin role uuid
      username: "adminuser",
      email: `admin_${Date.now()}@test.com`,
      password: "StrongPassword1!",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(adminUser);

  // 2. Register a normal member
  const normalUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: "member-role-uuid", // replace with actual member role uuid
      username: "memberuser",
      email: `member_${Date.now()}@test.com`,
      password: "SafePass2?",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(normalUser);

  // 3. Create a post (as normal user)
  const category_id = "test-category-uuid"; // must exist in db
  const post = await api.functional.posts.posts.post(connection, {
    body: {
      category_id,
      title: "Soft-delete comment test post",
      content: "Testing deleted comment API permissions.",
      user_id: normalUser.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a comment (as normal user)
  const comment = await api.functional.posts.comments.post(connection, {
    body: {
      post_id: post.id,
      user_id: normalUser.id,
      content: "Original content to be deleted.",
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 5. Soft-delete the comment (as admin)
  const deleted_at = new Date().toISOString();
  const deletedComment = await api.functional.posts.comments.putById(connection, {
    id: comment.id,
    body: {
      deleted_at,
    } satisfies IComment.IUpdate,
  });
  typia.assert(deletedComment);
  TestValidator.equals("Soft deleted")(deletedComment.deleted_at)(deleted_at);

  // 6a. Retrieve deleted comment detail as admin (should succeed)
  const adminViewed = await api.functional.posts.comments.getById(connection, { id: comment.id });
  typia.assert(adminViewed);
  TestValidator.equals("Admin can see deleted comment")(comment.id)(adminViewed.id);
  TestValidator.equals("Comment is marked deleted")(adminViewed.deleted_at)(deleted_at);

  // 6b. Retrieve deleted comment as normal user (should fail: forbidden/notFound)
  await TestValidator.httpError("Member cannot view deleted comment detail")(403, 404)(() =>
    api.functional.posts.comments.getById(connection, { id: comment.id })
  );

  // 6c. Retrieve non-deleted comment as admin/normal user (create new comment)
  const newComment = await api.functional.posts.comments.post(connection, {
    body: {
      post_id: post.id,
      user_id: normalUser.id,
      content: "Active comment for control.",
    } satisfies IComment.ICreate,
  });
  typia.assert(newComment);

  // Admin fetches active comment
  const adminActiveDetail = await api.functional.posts.comments.getById(connection, { id: newComment.id });
  typia.assert(adminActiveDetail);
  TestValidator.equals("Active comment detail")(newComment.id)(adminActiveDetail.id);
  TestValidator.equals("Active comment not deleted")(null)(adminActiveDetail.deleted_at as null);

  // Normal user fetches active comment
  const memberActiveDetail = await api.functional.posts.comments.getById(connection, { id: newComment.id });
  typia.assert(memberActiveDetail);
  TestValidator.equals("Active comment detail for member")(newComment.id)(memberActiveDetail.id);
  TestValidator.equals("Active comment not deleted for member")(null)(memberActiveDetail.deleted_at as null);
}

