import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Validate error handling when creating a reply to an invalid parent comment.
 *
 * This test ensures that when a user tries to create a reply with a parentId
 * that does not exist, or that is not associated with the same post, the API
 * correctly rejects the request with an error response.
 *
 * Steps:
 * 1. Register a new user who will attempt to reply (required for authentication).
 * 2. Create a post for context for comments/replies.
 * 3. Attempt to create a reply with a random (non-existent) parentId; expect error.
 * 4. Create a valid comment on Post A.
 * 5. Create a second post (Post B).
 * 6. Attempt to reply to the comment from Post A, but wrongly specify post_id as Post B; expect error.
 */
export async function test_api_comment_reply_invalid_parent(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register user
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: `errtest_user_${Math.random().toString(36).slice(2)}`,
      email: `errtest_email_${Math.random().toString(36).slice(2)}@example.com`,
      password: "errorpass1234!",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a valid post (Post A)
  const postA: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Error handling test post A",
      content: "Testing invalid parent reply for post A.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postA);

  // 3. Attempt reply with non-existent parentId
  const invalidParentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("Reply with non-existent parentId should fail")(400, 404)(() =>
    api.functional.posts.comments.post(connection, {
      body: {
        user_id: user.id,
        post_id: postA.id,
        parent_id: invalidParentId,
        content: "Should fail: parent does not exist.",
      } satisfies IComment.ICreate,
    })
  );

  // 4. Create a valid comment on Post A
  const baseComment: IComment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: postA.id,
      content: "This is the base comment for Post A.",
    } satisfies IComment.ICreate,
  });
  typia.assert(baseComment);

  // 5. Create a second post (Post B)
  const postB: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Error handling test post B",
      content: "Testing mismatch between post and comment parent.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postB);

  // 6. Attempt to add a reply to the comment, but with mismatched post_id
  await TestValidator.httpError("Reply to valid comment but with mismatched post_id should fail")(400, 404)(() =>
    api.functional.posts.comments.post(connection, {
      body: {
        user_id: user.id,
        post_id: postB.id, // NOT the same as baseComment.post_id
        parent_id: baseComment.id, // base comment from postA
        content: "Should fail: mismatched post and parent.",
      } satisfies IComment.ICreate,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Test editing an existing comment's content within allowed time window and by the original author.
 *
 * This test validates that a comment can be edited by its author within the permitted window, and that
 * the updated content is reflected in get results. It also ensures audit fields like 'updated_at' are
 * incremented, and key references are unchanged.
 *
 * Steps:
 * 1. Register user
 * 2. Create post
 * 3. Create comment
 * 4. Update comment content
 * 5. Verify updated content and audit fields
 */
export async function test_api_comment_update_comment_content_success(connection: api.IConnection): Promise<void> {
  // 1. Register user
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const username = `user_${Math.random().toString(36).slice(2, 10)}`;
  const email = `${username}@example.com`;
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username,
      email,
      bio: "Test user for comment update",
      password: "test-password",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create post
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test Post for Comment Update",
      content: "Initial content for post.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 3. Create comment
  const originalContent = "Original comment body";
  const comment: IComment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      content: originalContent,
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("Initial content matches")(originalContent)(comment.content);

  // 4. Update comment content
  const updatedContent = "Updated comment body (after edit)";
  const updated: IComment = await api.functional.posts.comments.putById(connection, {
    id: comment.id,
    body: {
      content: updatedContent,
    } satisfies IComment.IUpdate,
  });
  typia.assert(updated);

  // 5. Verify updated content and audit fields
  TestValidator.equals("Updated comment ID unchanged")(comment.id)(updated.id);
  TestValidator.equals("User remains same")(comment.user_id)(updated.user_id);
  TestValidator.equals("Post remains same")(comment.post_id)(updated.post_id);
  TestValidator.equals("Content updated")(updatedContent)(updated.content);
  TestValidator.predicate("updated_at has changed and is after created_at")(() => new Date(updated.updated_at) > new Date(comment.updated_at));
  TestValidator.equals("Not deleted after update")(updated.deleted_at)(null);
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
