import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Ensure that updating a soft-deleted comment results in a forbidden error.
 *
 * This scenario validates that once a comment is soft-deleted (i.e., marked as deleted by setting `deleted_at`), no further updates should be possible. This enforces business logic and protects moderation integrity, regardless of who attempts to update the deleted comment.
 *
 * Flow:
 * 1. Register a new user (to act as comment author)
 * 2. Create a post as the context for the comment
 * 3. Create a comment under the post as the user
 * 4. Soft-delete the comment (set `deleted_at`)
 * 5. Attempt to update the content or metadata of the already-deleted comment
 *    and assert that the backend returns a relevant error (preferably 403 or 409)
 */
export async function test_api_comment_update_after_soft_delete_forbidden(connection: api.IConnection): Promise<void> {
  // 1. Register a user
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: `forbidden-user-${Math.random()}`,
      email: `forbidden-user-${Math.random()}@e2e.com`,
      password: "testpass",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a post for the user to comment on
  const post = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Soft delete comment E2E test",
      content: "Soft delete business rules verification.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a comment under the post
  const comment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      content: "Original comment: should not be editable after deletion.",
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("comment created; not deleted yet")(comment.deleted_at ?? null)(null);

  // 4. Soft delete the comment
  const deleted_at = new Date().toISOString();
  const softDeleted = await api.functional.posts.comments.putById(connection, {
    id: comment.id,
    body: {
      deleted_at,
    } satisfies IComment.IUpdate,
  });
  typia.assert(softDeleted);
  TestValidator.equals("comment soft deleted: deleted_at set")(softDeleted.deleted_at)(deleted_at);

  // 5. Attempt to update the comment (should fail)
  await TestValidator.httpError("Cannot update a soft-deleted comment")(403, 409)(() =>
    api.functional.posts.comments.putById(connection, {
      id: comment.id,
      body: {
        content: "Modified body after soft-delete should fail",
      },
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
