/**
 * E2E test for creating and soft-deleting a comment.
 *
 * Scenario: A user registers, creates a post, adds a comment, then soft-deletes that comment.
 * Each step validates the results using TestValidator and typia.assert.
 *
 * Steps:
 * 1. Register a user who will author and delete the comment
 * 2. Create a post for the comment to attach to
 * 3. Create a comment to be deleted
 * 4. Soft-delete the comment as its author
 */
export async function test_api_post_comment_soft_delete(
  connection: api.IConnection
): Promise<void> {
  // 1. Register a user who will author and delete the comment
  const MEMBER_ROLE_ID = "00000000-0000-0000-0000-000000000001"; // Assume fixed 'member' role
  const username = `user_${Math.random().toString(36).substring(2, 10)}`;
  const email = `${username}@test.local`;
  const user = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: MEMBER_ROLE_ID,
      username,
      email,
      bio: "Comment author & deleter",
      password: "test-password-1234",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);
  TestValidator.equals("Verify registered user role")(user.user_role_id)(MEMBER_ROLE_ID);

  // 2. Create a post for the comment to attach to
  const post = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: "00000000-0000-0000-0000-000000000100", // Dummy valid category
      title: "Test post for comment delete E2E",
      content: "Content body for test post.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("Post author match")(post.user_id)(user.id);

  // 3. Create a comment to be deleted
  const commentContent = `Comment for soft-delete test: ${Date.now()}`;
  const comment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      content: commentContent,
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("Comment author matches")(comment.user_id)(user.id);
  TestValidator.equals("Comment content matches")(comment.content)(commentContent);

  // 4. Soft-delete the comment as its author
  const deleteResult = await api.functional.posts.comments.eraseById(connection, {
    id: comment.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("Deleted comment ID")(deleteResult.id)(comment.id);
  TestValidator.equals("Mark as deleted")(deleteResult.deleted)(true);
}

