    body: {
      user_role_id: typia.random<string & tags.Format<"uuid">>(),
      username: `other_${Date.now()}`,
      email: `other_${Date.now()}@example.com`,
      password: "pw1234!",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(testUser);

  // 3. Create a post as the author
  const post = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Sample Post For Comment Deletion Test",
      content: "Sample post content.",
      user_id: author.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a comment as the author on the post
  const comment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: author.id,
      post_id: post.id,
      content: "Comment to test forbid delete.",
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 5. Attempt to delete as a different user (not author, not admin/mod)
  // Simulate login as the different user if session required (depends on implementation)
  await TestValidator.httpError("Non-owner, non-admin should be forbidden to delete the comment")(403)(() =>
    api.functional.posts.comments.eraseById(connection, {
      id: comment.id,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
