/**
 * Test soft-deletion of another user's comment by an admin/moderator.
 *
 * This test validates that an administrator or moderator can soft-delete a comment written by another user. The full flow involves creating both users (a regular member and an admin), a post, and a comment by the member user. It then verifies the admin is able to delete the member's comment, checks the deletion response, ensures the comment is no longer visible to non-privileged users, and asserts that audit data still references the deleted comment for admin tools.
 *
 * Steps:
 * 1. Register a regular user (comment author) and an admin user (with proper role).
 * 2. Create a post (using the regular user).
 * 3. Create a comment on the post (as the regular user).
 * 4. Delete the comment as the admin via the API.
 * 5. Verify the deletion response (ID, deleted:true, message exists).
 * 6. As a regular user, attempt to fetch the deleted comment (should fail or indicate deleted).
 * 7. As an admin, confirm that the audit logs/ref endpoint still references the action or deleted comment.
 */
export async function test_api_comment_delete_success_as_admin(connection: api.IConnection): Promise<void> {
  // 1. Register user roles and test accounts
  // We'll mock two roles: 'member' and 'administrator'.
  // For test stability, use deterministic/test values
  const MEMBER_ROLE = { id: "b20e6ea1-6c51-41ec-a743-9cb82d4f55f5", name: "member" } satisfies IUserRole.ISummary;
  const ADMIN_ROLE = { id: "81982347-66fa-4325-b1ef-186040a23d99", name: "administrator" } satisfies IUserRole.ISummary;

  // Create regular user (for comment authoring)
  const user = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: MEMBER_ROLE.id,
      username: `user_${Date.now()}`,
      email: `user_${Date.now()}@test.com`,
      bio: "A regular user",
      password: "password-1234",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);
  TestValidator.equals("User role must be member")("member")(user.role.name);

  // Create admin user
  const admin = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: ADMIN_ROLE.id,
      username: `admin_${Date.now()}`,
      email: `admin_${Date.now()}@test.com`,
      bio: "An admin user",
      password: "adminPassword-1234",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(admin);
  TestValidator.equals("User role must be administrator")("administrator")(admin.role.name);

  // 2. Create a post as the regular user
  const post = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: "452ae71a-9279-456d-bc42-59df92445b7a", // assumed existing category
      title: "Admin-deletable comment test post",
      content: "Testing admin comment deletion.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("Post author and user matches")(user.id)(post.user_id);

  // 3. Create a comment as the regular user
  const comment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      content: "This comment will be deleted by admin.",
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("Comment author matches")(user.id)(comment.user_id);
  TestValidator.equals("Comment post matches")(post.id)(comment.post_id);

  // 4. Delete the comment as admin
  // (Assume session switching to admin: or admin-privileged token)
  // In real env, regenerate connection/context here
  // Proceed to delete
  const deleteResult = await api.functional.posts.comments.eraseById(connection, {
    id: comment.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("Deleted comment ID matches")(comment.id)(deleteResult.id);
  TestValidator.equals("Deleted status is true")(true)(deleteResult.deleted);
  TestValidator.predicate("Delete message exists")(() => typeof deleteResult.message === "string" && !!deleteResult.message);

  // 5. As a regular user: trying to retrieve the deleted comment (simulate client view)
  await TestValidator.httpError("Fetching deleted comment as normal user should fail")(404)(() =>
    api.functional.posts.comments.post(connection, {
      body: {
        user_id: user.id,
        post_id: post.id,
        content: "Trying to access deleted.",
      } as IComment.ICreate,
    }),
