 * This E2E test covers the admin operation of listing users with advanced filters and pagination support, according to board moderation requirements. It verifies user and role creation, and validates filtered search, edge cases, and data privacy.
 *
 * 1. Create user roles (member, moderator, administrator)
 * 2. Register several users with diverse usernames, emails, roles, and statuses
 * 3. As an administrator, retrieve a paginated list with filters: username, email domain, role
 * 4. Confirm filtering by username and email
 * 5. Confirm filtering by role
 * 6. Confirm pagination and metadata correctness
 * 7. Validate no sensitive fields (like passwords or hashes) appear in results
 * 8. Test edge cases: zero results, large page size, sort order (if supported)
 */
export async function test_list_users_with_valid_filters_pagination_and_admin_access(connection: api.IConnection): Promise<void> {
  // 1. Create user roles
  const memberRole = await api.functional.core.userRoles.post(connection, {
    body: { name: "member", description: "Standard member role" } satisfies IUserRole.ICreate,
  });
  typia.assert(memberRole);
  const moderatorRole = await api.functional.core.userRoles.post(connection, {
    body: { name: "moderator", description: "Moderator" } satisfies IUserRole.ICreate,
  });
  typia.assert(moderatorRole);
  const adminRole = await api.functional.core.userRoles.post(connection, {
    body: { name: "administrator", description: "Administrator" } satisfies IUserRole.ICreate,
  });
  typia.assert(adminRole);

  // 2. Register users with varied attributes
  const users = [
    {
      user_role_id: memberRole.id,
      username: "alice-main",
      email: "alice@example.com",
      bio: "Alice the member",
      password: "password1",
      status: "active",
    },
    {
      user_role_id: moderatorRole.id,
      username: "bob-mod",
      email: "bob@modmail.net",
      bio: null,
      password: "password2",
      status: "active",
    },
    {
      user_role_id: adminRole.id,
      username: "carol-admin",
      email: "carol@admin.org",
      bio: "Carol the Admin",
      password: "password3",
      status: "banned",
    },
    {
      user_role_id: memberRole.id,
      username: "dave-user",
      email: "dave@userspace.net",
      bio: "Just Dave",
      password: "password4",
      status: "suspended",
    },
  ];

  const createdUsers: IUser[] = [];
  for (const u of users) {
    const created = await api.functional.core.users.post(connection, {
      body: u satisfies IUser.ICreate,
    });
    typia.assert(created);
    createdUsers.push(created);
  }

  // 3. As administrator, test list: filter username partial, email domain
  // (assuming adminRole is the active session/user for this test API)

  // Username partial match
  const usernameFilter = await api.functional.core.users.patch(connection, {
    body: {
      search: "ali",
    } satisfies IUser.IRequest,
  });
  typia.assert(usernameFilter);
  TestValidator.predicate("Filter for username partial match")(() =>
    usernameFilter.data.some(
      (user) => user.username.toLowerCase().includes("ali")
    )
  );
  TestValidator.equals("Username filter pagination default")(
    true
  )(typeof usernameFilter.pagination.current === "number");

  // Email domain filter
  const emailDomainFilter = await api.functional.core.users.patch(connection, {
    body: {
      search: "@modmail.net",
    } satisfies IUser.IRequest,
  });
  typia.assert(emailDomainFilter);
  TestValidator.equals("Should retrieve only Bob by modmail.net filter")(
    1
  )(emailDomainFilter.data.length);
  TestValidator.equals("Email username matches")(
    "bob-mod"
  )(emailDomainFilter.data[0].username);

  // Role filter (moderator)
  const moderatorFilter = await api.functional.core.users.patch(connection, {
    body: {
      role: moderatorRole.id,
    } satisfies IUser.IRequest,
  });
  typia.assert(moderatorFilter);
  TestValidator.predicate("All returned users must have moderator role")(() =>
    moderatorFilter.data.every((user) => user.role.id === moderatorRole.id)
  );

  // Status filter (suspended)
  const suspendedFilter = await api.functional.core.users.patch(connection, {
    body: {
      status: "suspended",
    } satisfies IUser.IRequest,
  });
  typia.assert(suspendedFilter);
  TestValidator.predicate("All users returned are suspended")(() =>
    suspendedFilter.data.every((user) => user.status === "suspended")
  );

  // 6. Pagination: limit/page
  const paginationFilter = await api.functional.core.users.patch(connection, {
    body: {
      limit: 2,
    } satisfies IUser.IRequest,
  });
  typia.assert(paginationFilter);
  TestValidator.equals("Should only return two users per page")(
    2
  )(paginationFilter.data.length);
  TestValidator.predicate("Pages should be correct")(() =>
    typeof paginationFilter.pagination.pages === "number"
  );

  // 7. Data privacy check
  for (const user of paginationFilter.data) {
    TestValidator.predicate("No password field returned in summary")(() =>
      !("password" in user)
    );
    TestValidator.predicate("No email returned in summary")(() =>
      !("email" in user)
    );
  }

  // 8. Edge case: filter for non-existent username (zero results)
  const emptySearch = await api.functional.core.users.patch(connection, {
    body: {
      search: "ZZZZ-doesnotexist",
    } satisfies IUser.IRequest,
  });
  typia.assert(emptySearch);
  TestValidator.equals("Should find no user for unmatched username")(
    0
  )(emptySearch.data.length);

  // Edge case: very large limit (should cap to available data)
  const largeLimit = await api.functional.core.users.patch(connection, {
    body: {
      limit: 100,
    } satisfies IUser.IRequest,
  });
  typia.assert(largeLimit);
  TestValidator.predicate("Returned users should never exceed limit")(() =>
    largeLimit.data.length <= 100
  );
}

