 * Validate deleting a non-existent user as an admin returns correct error.
 *
 * This test ensures that when an administrator attempts to delete a user ID that does not exist (or has already been deleted), the system responds with an appropriate not found error and does not disclose any sensitive data in the response. It also confirms the returned HTTP status code is correct.
 *
 * 1. Create an admin user role (for permissioned deletion)
 * 2. Register admin user with the created role
 * 3. Attempt to delete a random (likely non-existent) user ID as the admin
 * 4. Assert system returns a not found error (404 or equivalent)
 */
export async function test_api_user_delete_nonexistent_user_returns_not_found(connection: api.IConnection): Promise<void> {
  // 1. Create an admin role
  const role: IUserRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: `administrator-${Math.random().toString(36).substring(2, 10)}`,
      description: "Administrator role for test."
    } satisfies IUserRole.ICreate
  });
  typia.assert(role);

  // 2. Register the admin user
  const adminUser: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: role.id,
      username: `admin_${Math.random().toString(36).substring(2, 12)}`,
      email: `admin_${Date.now()}@test.com`,
      password: "1234SecurePassword",
      bio: "Test admin user.",
      status: "active"
    } satisfies IUser.ICreate
  });
  typia.assert(adminUser);

  // (Assume session/auth adjustment is handled by test runner, or supply auth headers if custom token is needed)

  // 3. Attempt to delete a random (very likely non-existent) user ID
  const randomUserId: string & tags.Format<"uuid"> =
    typia.random<string & tags.Format<"uuid">>();

  // Ensure randomUserId is not already used (different from admin just created)
  if (randomUserId === adminUser.id) throw new Error("Random user ID collision in test setup.");

  // 4. Assert correct error is thrown (404 not found)
  await TestValidator.httpError("Non-existent user deletion must return not-found error")(404)(() =>
    api.functional.core.users.eraseById(connection, { id: randomUserId })
  );
}
